    /**
     * Rollover image in search results
     */
    public function getSearchRolloverImage(): ?Gallery
    {
        return $this->parent?->loadFile('img_1_rollover');
    }


    /**
     * Get the JSON-LD representation of the product variant.
     */
    public function toJsonLd(string $url): array
    {
        $parent = $this->parent;
        $parentLang = $parent?->current_lang;
        $category = $this->category;

        $data = [
            '@context'    => 'https://schema.org',
            '@type'       => 'Product',
            'name'        => $parent?->name ?? $this->name,
            'url'         => $url,
            'sku'         => $this->code,
            'mpn'         => $this->code,
            'brand'       => [
                '@type' => 'Brand',
                'name'  => 'Italamp',
            ],
            'manufacturer' => [
                '@type' => 'Organization',
                'name'  => 'Italamp',
                'url'   => config('app.url'),
            ],
        ];

        if ($parentLang?->description) {
            $data['description'] = strip_tags(str_replace(PHP_EOL, ' ', $parentLang->description));
        }

        if ($category?->current_lang?->title) {
            $data['category'] = $category->current_lang->title;
        }

        $image = $parent?->image('img_2', '');
        if ($image) {
            $data['image'] = url($image);
        }

        $parent?->loadMissing('designers');
        if ($parent && $parent->designers->count()) {
            $data['additionalProperty'] = $parent->designers->map(fn ($designer) => [
                '@type' => 'PropertyValue',
                'name'  => 'designer',
                'value' => $designer->name,
            ])->values()->all();
        }

        return $data;
    }
}

